function badge(value){const label=human(value||'unknown');const cls=/reject|fail|block|withdraw/i.test(label)?'red':/condition|unresolved|pending|unqualified|draft/i.test(label)?'amber':/unknown|unavailable|not implemented/i.test(label)?'gray':'';return `<span class="badge ${cls}">${esc(label)}</span>`;}
function jsonBlock(value){return `<pre class="json-record">${esc(pretty(value))}</pre>`;}
function strings(value){if(Array.isArray(value))return value.map(text).filter(Boolean);return value?[text(value)]:[];}
function prose(value,fallback='Not recorded.'){const v=strings(value);return v.length?v.join(' '):fallback;}
function citations(values){const ids=array(values);return ids.length?`<div class="citation-list">${ids.map(x=>`<button type="button" class="citation" data-citation="${esc(x)}">${esc(x)}</button>`).join('')}</div>`:'<p>No source-specific citation recorded.</p>';}
async function api(path,options={}){const init={...options,headers:{'Content-Type':'application/json',...(options.headers||{})}};if(init.body!==undefined)init.body=JSON.stringify(init.body);const response=await fetch(path,init);let value;try{value=await response.json();}catch{throw new Error(`The server returned an unreadable response (${response.status}).`);}if(!response.ok){const detail=value.error||value.detail||value.message||value;const error=new Error(typeof detail==='string'?detail:JSON.stringify(detail));error.payload=value;throw error;}return value;}
