function updateModelNote(){const value=$('#model-route').value;$('#custom-model-wrap').classList.toggle('hidden',value!=='custom');const model=state.models.find(m=>(m.id||m.route_id)===value),quota=modelAllowance();const limit=quota.limit==null?'':`Qwen allowance: ${quota.used??0}/${quota.limit} attempts used${quota.exhausted?' · exhausted; no further calls authorized.':'.'}`;$('#model-note').textContent=value==='custom'?'This route is unavailable in the current campaign.':model?.available===false?(model.reason||'This route is unavailable.'):value==='deterministic'?`Offline selection only; no model call or automatic route fallback. ${limit}`:`Private server: ${model?.model||model?.id||''}. ${limit} ${quota.exhausted?'Generation is disabled for this route. Select Offline coverage selection to generate without a model.':'Actual calls and responses are archived with the round.'}`;updateGenerateAvailability();}
