async function loadCampaign(id,{preserveRound=false}={}){const token=++state.requestToken;const loaded=await api('/api/campaigns/'+encodeURIComponent(id));if(token!==state.requestToken)return;const nextCampaign=loaded.campaign||loaded;if(state.campaign?.id!==nextCampaign.id){state.questionProposal=null;message('#question-proposal-context','');$('#question-form').reset();}state.campaign=nextCampaign;const latest=state.campaign.latest_round||state.campaign.last_round||loaded.latest_round;let round=preserveRound&&state.round?.campaign_id===id?(array(state.campaign.rounds).find(x=>x.id===state.round.id)||state.round):null;if(!round&&latest&&typeof latest==='object')round=latest;if(!round){const rounds=array(state.campaign.rounds);const last=rounds.at(-1);if(last&&(last.selected||last.conditions))round=last;else if(last){const response=await api(`/api/rounds/${encodeURIComponent(id)}/${encodeURIComponent(last.id||last.round_id)}`);if(token!==state.requestToken)return;round=response.round||response;}}state.round=round;state.selected=0;fillCampaignSelect();hydrateForms();fillModels();renderCampaign();renderRound();const currentURL=new URL(location.href);currentURL.searchParams.set('campaign',state.campaign.id);history.replaceState(null,'',currentURL.pathname+currentURL.search+currentURL.hash);}
