function inventoryItems(inv){if(Array.isArray(inv?.items))return inv.items;const source=inv?.lab_inventory||inv||{};return Object.values(source).filter(Array.isArray).flat().filter(x=>x&&typeof x==='object'&&(x.equipment_id||x.id||x.name));}
