function modelReview(){return state.round?.model_review||state.round?.request?.model_review||state.round?.model_assessment||state.round?.model_plan||{};}
function scientificReviewSummary(review){const audit=review?.scientific_review;if(!audit)return '';const status=audit.status||audit.disposition||'pending';if(scientificReviewFailed(review))return 'The model hypothesis review failed. The feasible settings remain conditional; curated planning questions are shown here. Unsupported model hypotheses and the review findings remain visible in Questions and the full record.';if(/pending/i.test(status))return 'Scientific reasoning review is pending. These are unvalidated model proposals, with no laboratory release or measured flow outcomes.';return 'Scientific reasoning review: '+human(status)+'. The proposed conditions remain conditional and experimentally unvalidated; hypotheses require researcher review and prospective measurements.';}
function scientificReviewFailed(review){return /fail|reject/i.test(text(review?.scientific_review?.status||review?.scientific_review?.disposition));}
function modelRationale(row){const review=modelReview();if(scientificReviewFailed(review))return {};return array(review.parsed?.design_rationales||review.design_rationales).find(r=>r.candidate_id===(row.candidate_id||row.id))||row.model_rationale||{};}
