function parameterValue(value){return value!==null&&typeof value==='object'&&!Array.isArray(value)&&Object.prototype.hasOwnProperty.call(value,'value')?value.value:value;}
function param(row,names){const sources=[row.parameters||{},row.calculated||{},row.proposed_setpoints||{},row];for(const source of sources)for(const key of names){const value=parameterValue(source[key]);if(value!==undefined&&value!==null)return value;}return null;}
