function renderConditionBasis(){const rows=selected(),common=names=>{const values=rows.map(r=>param(r,names));return values.length&&values.every(v=>v!=null&&v===values[0])?values[0]:null;};const bits=[];const temp=common(['gas_reference_temperature_K_assumed']),pressure=common(['gas_reference_pressure_bar_abs_assumed']),reactor=common(['reactor_pressure_bar_abs_assumed']),bpr=common(['bpr_label_value_bar']),basis=common(['bpr_label_basis_assumption']);if(temp!=null&&pressure!=null)bits.push(`Gas reference: ${fmt(temp-273.15)} °C / ${fmt(pressure,5)} bar absolute (assumed)`);if(reactor!=null)bits.push(`Reactor pressure: ${fmt(reactor,5)} bar absolute (assumed${bpr!=null&&basis?', '+fmt(bpr)+' bar BPR interpreted as '+basis:''})`);if(common(['feed_mode'])==='sample_loop')bits.push('Sample-loop volume, actual contact time and collection window: unknown');$('#conditions-basis').textContent=bits.join(' · ');$('#conditions-basis').classList.toggle('hidden',!bits.length);}
