function renderBasis(){const r=state.round;const limitations=[...strings(r.limitations),...strings(r.assumptions),...strings(r.configuration?.assumptions),...strings(r.configuration?.limitations),...strings(r.evidence_boundary)];$('#basis-tab').innerHTML=`<div class="basis-content"><h3>Authority and status</h3><p>Proposed settings, calculated estimates and actual observations are stored separately. ${r.laboratory_released===true?'Laboratory release is recorded in this round.':'Laboratory release is not recorded for this round.'}</p>${limitations.length?'<ul>'+limitations.map(v=>`<li>${esc(v)}</li>`).join('')+'</ul>':''}<details><summary>Configuration and source hashes</summary>${jsonBlock({configuration:r.configuration,source_hashes:r.source_hashes,questions_snapshot:r.questions_snapshot,limitations:r.limitations})}</details></div>`;}
function localImagePath(value){if(typeof value!=='string'||value.includes('..')||value.includes('\\'))return null;if(/^diagrams\/[A-Za-z0-9_.-]+\.(svg|png)$/.test(value)&&String(state.round?.configuration?.profile_id||spec().profile_id||'').toLowerCase().includes('khu'))return '/assets/khu/'+value;if(!value.startsWith('/')||value.startsWith('//'))return null;return value;}
function renderDesign(){const row=selected()[state.selected];if(!row)return;const modeled=modelRationale(row),q=frozenQuestions().find(q=>array(row.question_ids).includes(q.id));$('#detail-number').textContent=`DESIGN ${idOf(row)} / ${row.candidate_id&&row.candidate_id!==row.id?row.candidate_id:'PROPOSED CONDITION'}`;$('#design-question').textContent=selectedQuestion(row);$('#design-status').textContent=human(row.engineering_status||row.status||'conditional');const diagram=localImagePath(row.diagram_url||row.diagram_png_url||row.topology?.diagram_url||row.diagram?.url);$('#design-diagram').innerHTML=diagram?`<img src="${esc(diagram)}" alt="FlowPilot apparatus proposal for ${esc(idOf(row))}">`:'<div class="diagram-placeholder">A rendered topology was not supplied for this candidate.<br>Inspect its structured equipment and connection record below.</div>';const reasons=row.rationale?.why_this_condition||row.rationale?.hypothesis||row.rationale||row.selection_reasons||row.selection_reason;const expected=row.expected_contrast||modeled.expected_observations||row.expected_observations||q?.expected_observations;const confounders=row.confounders||modeled.confounders||q?.confounders;const evidence=modeled.evidence_ids||row.evidence_ids||q?.evidence_ids;$('#design-explanation').innerHTML=`<div class="explanation-block"><h3>Why this condition</h3><p>${esc(prose(reasons,'No condition-specific rationale was returned.'))}</p></div><div class="explanation-block"><h3>Expected contrast · hypothesis</h3><p>${esc(prose(expected,'Expected observations have not been specified. No yield prediction is implied.'))}</p></div><div class="explanation-block"><h3>Evidence available to the design</h3>${citations(evidence)}</div><div class="explanation-block"><h3>Confounders & next decision</h3><p>${esc(prose(confounders,'Confounders are not yet documented.'))} ${esc(prose(modeled.next_decision||row.next_decision||q?.decision_rules,''))}</p></div>`;$('#diagram-note').textContent=row.diagram_note||'Equipment connectivity and settings are proposed; actual operation remains separate.';$('#design-diagram img')?.addEventListener('error',()=>{$('#design-diagram').innerHTML='<p class="diagram-placeholder">The topology image could not be loaded. Its source path remains in the exact design record.</p>';});}
