function sourceRows(){const evidence=array(spec().evidence||state.campaign?.evidence);return evidence.flatMap(e=>Array.isArray(e.rows)?e.rows:Array.isArray(e.records)?e.records:[e]);}
function renderEvidence(){state.evidence=sourceRows();const rows=state.evidence;$('#nav-evidence').textContent=rows.length;const sourceSet=new Set(rows.flatMap(r=>array(r.source_representations).map(s=>s.source_id||s.source_sha256||s.sha256)).filter(Boolean));const issues=rows.filter(r=>r.interpretation_eligible===false||array(r.disputed_fields||r.disputed_source_fields).length).length;const proposals=rows.filter(r=>r.record_kind==='proposal').length;$('#evidence-summary').innerHTML=roundMetric(rows.length,'retained records')+roundMetric(sourceSet.size||array(spec().source_references).length,'source references')+roundMetric(issues,'unresolved / excluded')+roundMetric(proposals,'proposal records');$('#evidence-banner-title').textContent=`${rows.length} retained evidence records · source-linked context`;$('#evidence-banner-text').textContent='Batch and flow observations stay distinct. Missing values and disputed exports remain visible.';renderEvidenceTable();}
function evidenceOutcomes(row){return row.reported_outcomes||row.analytes||row.outcomes||{};}
function objectSummary(object,limit=6){if(!object||typeof object!=='object')return text(object)||'—';return Object.entries(object).filter(([,v])=>v!==null&&v!==''&&v!==undefined).slice(0,limit).map(([k,v])=>`${human(k)}: ${typeof v==='object'&&v!==null&&'value'in v?`${fmt(v.value)} ${v.unit||''}`:fmt(v)}`).join(' · ')||'Not reported';}
function renderEvidenceTable(){const query=$('#evidence-search').value.trim().toLowerCase(),filter=$('#evidence-filter').value;const matching=state.evidence.map((row,i)=>({row,i})).filter(({row})=>(!query||JSON.stringify(row).toLowerCase().includes(query))&&(filter==='all'||filter==='proposal'&&row.record_kind==='proposal'||filter==='unresolved'&&(row.interpretation_eligible===false||array(row.disputed_fields||row.disputed_source_fields).length)||row.catalyst_system===filter));$('#evidence-rows').innerHTML=matching.map(({row,i})=>`<tr data-evidence="${i}" tabindex="0"><td><strong>${esc(row.record_id||row.id||row.source_entry||'Unassigned record')}</strong><small>${esc(row.catalyst_system||row.source_type||row.kind||'System unassigned')}</small></td><td>${esc(row.experiment_mode||'unknown')}</td><td class="compact-content">${esc(objectSummary(row.reported_actual_conditions||row.actual_conditions||row.conditions,5))}</td><td class="compact-content">${esc(objectSummary(evidenceOutcomes(row),6))}</td><td>${badge(row.record_kind==='proposal'?'proposal':row.interpretation_eligible===false?'unresolved / excluded':row.source_status||'retained evidence')}</td></tr>`).join('')||'<tr><td colspan="5" class="small-empty">No records match this view.</td></tr>';$('#evidence-footer').textContent=`${matching.length} of ${state.evidence.length} retained records shown. Click a row to inspect all source representations and original fields.`;$$('[data-evidence]').forEach(el=>{const open=()=>showRecord('Evidence record',state.evidence[Number(el.dataset.evidence)]);el.addEventListener('click',open);el.addEventListener('keydown',e=>{if(e.key==='Enter')open();});});}
$('#evidence-search').addEventListener('input',renderEvidenceTable);$('#evidence-filter').addEventListener('change',renderEvidenceTable);
function scientificFindingHTML(item){if(typeof item!=='object'||item===null)return `<li>${esc(text(item))}</li>`;const title=item.title||item.role||item.id||'Review finding';const fact=item.source_fact||item.finding||item.reason||item.message;const implication=item.implication||item.correction;return `<li data-review-finding="${esc(item.id||'')}"><strong>${esc(title)}</strong>${fact?`<p><strong>Source check:</strong> ${esc(fact)}</p>`:''}${implication?`<p><strong>Implication:</strong> ${esc(implication)}</p>`:''}${!fact&&!implication?'<p>See the full scientific audit for the retained finding.</p>':''}</li>`;}
function renderProposedQuestions(){const latest=state.campaign?.last_round||array(state.campaign?.rounds).at(-1);const review=latest?.model_review||latest?.request?.model_review||{};const proposals=array(review.parsed?.hypotheses);const scientific=review.scientific_review,blocked=scientificReviewFailed(review);const reviewFindings=array(scientific?.findings||scientific?.reasons||scientific?.issues);const disposition=scientific?`<div class="notice ${blocked?'error':'info'}"><strong>Scientific review: ${esc(human(scientific.status||scientific.disposition||'recorded'))}</strong>${blocked?'<p>These model hypotheses failed scientific review. Direct adoption is disabled. Retain the output for audit and write a corrected, unresolved question using the researcher form.</p>':''}${reviewFindings.length?'<details><summary>Source checks and implications · '+reviewFindings.length+' findings</summary><ul>'+reviewFindings.map(scientificFindingHTML).join('')+'</ul></details>':''}<button type="button" class="text-link" id="scientific-review-record">Full scientific audit <span>↗</span></button>${scientific.summary?`<p>${esc(scientific.summary)}</p>`:''}</div>`:'';$('#proposed-questions-panel').classList.toggle('hidden',!proposals.length);$('#proposed-questions-list').innerHTML=disposition+proposals.map((item,i)=>`<article class="proposed-question"><div class="card-top"><span class="overline">${esc(item.id||'MODEL PROPOSAL '+(i+1))}</span>${badge('unreviewed proposal')}</div><h3>${esc(item.question||'Question text not supplied')}</h3><p><strong>Competing explanations:</strong> ${esc(prose(item.competing_explanations))}</p><p><strong>Expected observations:</strong> ${esc(prose(item.expected_observations))}</p><p><strong>Confounders:</strong> ${esc(prose(item.confounders))}</p>${citations(item.evidence_ids)}<div class="button-group" style="margin-top:15px"><button type="button" class="text-link" data-model-question-record="${i}">Exact model proposal <span>↗</span></button><button type="button" class="button compact" data-review-model-question="${i}" ${blocked?'disabled title="Failed scientific review: write a corrected new question instead"':''}>${blocked?'Direct adoption unavailable':'Review in question form <span>→</span>'}</button></div></article>`).join('');$('#scientific-review-record')?.addEventListener('click',()=>showRecord('Full scientific audit — original claims and source checks',scientific));$$('[data-model-question-record]').forEach(el=>el.addEventListener('click',()=>showRecord('Unreviewed model question',proposals[Number(el.dataset.modelQuestionRecord)])));$$('[data-review-model-question]').forEach(el=>el.addEventListener('click',()=>{if(blocked)return;const proposal=proposals[Number(el.dataset.reviewModelQuestion)];const fill={ 'question-text':proposal.question,'question-hypothesis':strings(proposal.competing_explanations).join('\n'),'question-observations':strings(proposal.expected_observations).join('\n'),'question-measurements':strings(proposal.measurements).join('\n'),'question-decisions':strings(proposal.decision_rules).join('\n'),'question-confounders':strings(proposal.confounders).join('\n'),'question-evidence':array(proposal.evidence_ids).join(', ')};for(const [id,value] of Object.entries(fill))$('#'+id).value=value||'';state.questionProposal={source_round_id:latest.id,source_model_route:latest.model_route,source_proposal_id:proposal.id||null,source_call_id:review.chief?.call_id||review.call_id||null,adopted_as:'unresolved prospective question after explicit researcher form submission'};message('#question-proposal-context','Loaded an unreviewed model proposal. Edit its explanations, measurements and decision rules, then use Add to campaign. It will start unresolved; no mechanistic claim is accepted automatically.');$('#question-form').scrollIntoView({behavior:'smooth',block:'start'});$('#question-text').focus({preventScroll:true});toast('Proposal loaded for review. Nothing has been added to the campaign.');}));}
function renderQuestions(){renderProposedQuestions();const q=questions();$('#nav-questions').textContent=q.filter(x=>['unresolved','revised'].includes(x.status||'unresolved')).length;$('#question-list').innerHTML=q.map((item,i)=>`<article class="question-card"><div class="card-top"><span class="overline">${esc(item.id||`QUESTION ${i+1}`)}</span>${badge(item.status||'unresolved')}</div><h3>${esc(item.question||item.title)}</h3>${item.competing_explanations?.length?`<p>${esc(prose(item.competing_explanations))}</p>`:''}${item.expected_observations?.length?`<p><strong>Testable contrast:</strong> ${esc(prose(item.expected_observations))}</p>`:''}${citations(item.evidence_ids)}<div class="button-group" style="margin-top:16px"><button class="text-link" data-question-record="${i}">Full question <span>↗</span></button><button class="text-link" data-question-amend="${i}" style="margin-left:auto">Record an interpretation <span>→</span></button></div></article>`).join('')||'<div class="panel editor-panel"><p class="small-empty">No prospective questions have been recorded yet. Add one before selecting experiments.</p></div>';$$('[data-question-record]').forEach(el=>el.addEventListener('click',()=>showRecord('Scientific question',q[Number(el.dataset.questionRecord)])));$$('[data-question-amend]').forEach(el=>el.addEventListener('click',()=>amendQuestion(q[Number(el.dataset.questionAmend)])));}
function renderResultsTemplate(){const row=selected()[0];if(!row){$('#results-json').value='[]';return;}const configuration=state.round?.configuration||spec(),objective=configuration.objective||{};const keys=[...new Set([objective.metric||'product_yield',...array(objective.separate_components)])];const contract=configuration.observation_contract;let actual;if(contract){actual=JSON.parse(JSON.stringify(contract.actual_conditions_template||{}));const nullValues=obj=>{for(const key of Object.keys(obj)){if(obj[key]&&typeof obj[key]==='object'&&!Array.isArray(obj[key]))nullValues(obj[key]);else obj[key]=null;}};nullValues(actual);for(const path of array(contract.required_actual_conditions)){const parts=path.split('.');let cursor=actual;for(const key of parts.slice(0,-1)){if(!cursor[key]||typeof cursor[key]!=='object')cursor[key]={};cursor=cursor[key];}cursor[parts.at(-1)]=null;}}else{const actualKeys=Object.keys(row.actual||{});actual=Object.fromEntries((actualKeys.length?actualKeys:Object.keys(row.parameters||{})).map(k=>[k,null]));}if(!Object.keys(actual).length)actual.observation=null;$('#results-json').value=pretty([{id:'result-'+Date.now(),round_id:state.round.id,design_id:idOf(row),experiment_mode:'flow',actual_conditions:actual,analytes:Object.fromEntries(keys.map(k=>[k,{value:null,unit:objective.unit||'%'}])),analytical_method:{status:'unknown',name:null},outcome_status:'unqualified',quality:{accepted:false,basis:'Not assessed'}}]);}
function renderResults(){const data=results();const qualified=data.filter(r=>r.outcome_status==='qualified'&&r.quality?.accepted===true);$('#learning-summary').innerHTML=`<div class="learning-stat"><strong>${qualified.length}</strong><span>qualified result${qualified.length===1?'':'s'}<br>${data.length} total retained records</span></div><p class="field-note">Next-round selection uses only the evidence permitted by its recorded policy. Qualitative interpretations require an explicit question amendment; failed assays do not become zero yields.</p>`;$('#result-records').innerHTML=data.map((row,i)=>`<article class="result-record"><div class="requirement-top"><strong>${esc(row.id||row.run_id)}</strong>${badge(row.outcome_status||row.status||'unqualified')}</div><p>${esc(row.design_id||row.condition_id||'Unlinked design')} · ${esc(row.analytical_method||'Analytical method not recorded')}</p><p>${esc(objectSummary(row.analytes||row.outcomes))}</p><button class="text-link" data-result-record="${i}">Actuals & source record <span>↗</span></button></article>`).join('')||'<p class="small-empty">No flow outcomes are recorded. All current designs remain prospective.</p>';$$('[data-result-record]').forEach(el=>el.addEventListener('click',()=>showRecord('Measured result',data[Number(el.dataset.resultRecord)])));renderResultsTemplate();}
function renderArchives(){const rounds=array(state.campaign?.rounds);$('#round-list').innerHTML=[...rounds].reverse().map(r=>`<article class="archive-row"><div><h3>${esc(r.label||r.id||r.round_id)}</h3><p>Input version ${esc(r.campaign_version??'?')} · ${esc(date(r.created_at||r.frozen_at))}</p></div><div class="archive-meta"><span class="muted">${r.selected_count??r.requested_count??array(r.selected).length} conditions</span>${badge(r.status||'archived')}<button class="button compact" data-open-round="${esc(r.id||r.round_id)}">Open round <span>↗</span></button></div></article>`).join('')||'<div class="editor-panel"><p class="small-empty">No design rounds have been archived for this campaign.</p></div>';$$('[data-open-round]').forEach(el=>el.addEventListener('click',async()=>{try{const loaded=await api(`/api/rounds/${encodeURIComponent(state.campaign.id)}/${encodeURIComponent(el.dataset.openRound)}`);state.round=loaded.round||loaded;state.selected=0;renderRound();view('studio');toast('Opened the frozen round. Current study edits are separate.');}catch(e){message('#global-error',e.message);}}));}
