function download(name,value,type='application/json'){const blob=new Blob([typeof value==='string'?value:pretty(value)+'\n'],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000);}
