$('#generate-form').addEventListener('submit',async event=>{event.preventDefault();if(state.busy||!state.campaign)return;message('#generation-error','');if($('#model-route').value==='qwen3.6-27b'&&modelAllowance().exhausted){message('#generation-error','The Qwen allowance is exhausted. No call was sent; select the offline route for deterministic selection.');return;}if(state.dirty){message('#generation-error','Save the edited study version before generating a round.');return;}const n=Number($('#design-count').value),r=Number($('#repeat-count').value);if(!Number.isInteger(n)||n<1||!Number.isInteger(r)||r<0){message('#generation-error','Enter a positive whole number of conditions and a nonnegative whole number of repeats.');return;}let route=$('#model-route').value;if(route==='custom'){try{route=JSON.parse($('#custom-model').value);}catch{message('#generation-error','Custom model route must be valid JSON.');return;}}const request={count:n,requested_count:n,repeat_count:r,objective_mode:$('#objective-mode').value,model_route:route,allow_conditional:$('#allow-conditional').checked,researcher_instructions:$('#round-instructions').value};setBusy(true);const started=Date.now();const timer=setInterval(()=>{$('#generation-elapsed').textContent=`${Math.floor((Date.now()-started)/1000)} seconds elapsed · waiting for the actual server response.`;},1000);try{const generated=await api(`/api/campaigns/${encodeURIComponent(state.campaign.id)}/generate`,{method:'POST',body:request});const round=generated.round||generated;await loadCampaign(state.campaign.id);state.round=round;state.selected=0;renderRound();renderArchives();toast('Design round saved with its inputs and selection record.');}catch(e){message('#generation-error',e.message);const attempt=e.payload?.attempt_id||e.payload?.details?.id;if(attempt){toast(`Rejected attempt retained: ${attempt}`);await loadCampaign(state.campaign.id,{preserveRound:true}).catch(()=>{});}}finally{clearInterval(timer);setBusy(false);}});
