$('#save-results').addEventListener('click',async()=>{message('#results-error','');if(state.busy)return;try{const records=JSON.parse($('#results-json').value);if(!Array.isArray(records)||!records.length)throw new Error('Supply a nonempty JSON array of measured-result records.');$('#save-results').disabled=true;await api(`/api/campaigns/${encodeURIComponent(state.campaign.id)}/results`,{method:'POST',body:{records}});await loadCampaign(state.campaign.id,{preserveRound:true});toast('Actual results retained. Previous design rounds are unchanged.');}catch(e){message('#results-error',e.message);}finally{$('#save-results').disabled=false;}});
$('#next-round').addEventListener('click',()=>{view('studio');$('#round-instructions').focus();toast('Review the objective and question for the next prospective round.');});
$('#question-form').addEventListener('submit',async event=>{event.preventDefault();message('#question-error','');const button=event.submitter;button.disabled=true;try{const hypothesis=$('#question-hypothesis').value.trim();const lines=id=>$('#'+id).value.split('\n').map(s=>s.trim()).filter(Boolean);const q={id:'question-'+Date.now(),question:$('#question-text').value.trim(),competing_explanations:lines('question-hypothesis'),expected_observations:lines('question-observations'),measurements:lines('question-measurements'),confounders:lines('question-confounders'),decision_rules:lines('question-decisions'),evidence_ids:$('#question-evidence').value.split(',').map(s=>s.trim()).filter(Boolean),status:'unresolved'};if(state.questionProposal)q.model_proposal_provenance={...state.questionProposal};await api(`/api/campaigns/${encodeURIComponent(state.campaign.id)}/questions`,{method:'POST',body:q});await loadCampaign(state.campaign.id,{preserveRound:true});event.target.reset();state.questionProposal=null;message('#question-proposal-context','');toast('Prospective question added to the campaign with unresolved status.');}catch(e){message('#question-error',e.message);}finally{button.disabled=false;}});
function amendQuestion(question){$('#record-title').textContent=question.id;$('#record-eyebrow').textContent='DOCUMENT A RESEARCHER INTERPRETATION';$('#record-body').innerHTML=`<p class="muted">${esc(question.question)}</p><form id="amend-form"><label for="amend-status">Qualitative status</label><select id="amend-status"><option value="unresolved">Unresolved</option><option value="supported">Supported by cited evidence</option><option value="contradicted">Contradicted by cited evidence</option><option value="revised">Revised</option><option value="retired">Retired</option></select><label for="amend-author">Author</label><input id="amend-author" required placeholder="Researcher name"><label for="amend-reason">Interpretation and reason</label><textarea id="amend-reason" rows="4" required></textarea><label for="amend-evidence">Evidence IDs (comma separated)</label><input id="amend-evidence" required><p class="field-note">This records a qualitative interpretation, not a Bayesian probability or automatic proof of mechanism.</p><div id="amend-error" class="notice error hidden" role="alert"></div><button class="button primary full" type="submit">Save question amendment</button></form>`;$('#amend-status').value=question.status||'unresolved';$('#record-dialog').showModal();$('#amend-form').addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;try{const amended={...question,status:$('#amend-status').value,amendment:{author:$('#amend-author').value.trim(),reason:$('#amend-reason').value.trim(),evidence_ids:$('#amend-evidence').value.split(',').map(s=>s.trim()).filter(Boolean)}};await api(`/api/campaigns/${encodeURIComponent(state.campaign.id)}/questions`,{method:'POST',body:amended});await loadCampaign(state.campaign.id,{preserveRound:true});$('#record-dialog').close();toast('Question amendment saved with its evidence and author.');}catch(e){message('#amend-error',e.message);}finally{button.disabled=false;}});}
function requirementRows(value){return array(Array.isArray(value)?value:value?.requirements||value?.items);}
async function loadBenchmark(){try{const [requirements,benchmark]=await Promise.all([api('/api/requirements'),api('/api/benchmark')]);state.bootstrap.requirements=requirements;state.bootstrap.benchmark=benchmark;renderBenchmark();updateModelNote();}catch(e){$('#benchmark-summary').innerHTML=`<p class="notice error">${esc(e.message)}</p>`;}}
function renderBenchmark(){const requirements=state.bootstrap?.requirements,benchmark=state.bootstrap?.benchmark;const reqs=requirementRows(requirements);$('#requirements-list').innerHTML=reqs.map(r=>`<details class="requirement"><summary class="requirement-top"><strong>${esc(r.title||r.requirement||r.description||r.id)}</strong>${badge(r.status||'not recorded')}</summary><p><strong>Request:</strong> ${esc(prose(r.request||r.description))}</p><p><strong>Implementation:</strong> ${esc(prose(r.implementation||r.notes))}</p><p><strong>Verification:</strong> ${esc(prose(r.verification))}</p><p><strong>Evidence:</strong> ${esc(prose(r.evidence))}</p><small class="muted">${esc(r.id||'')}</small></details>`).join('')||'<p class="small-empty">No requirement records were returned.</p>';if(!benchmark){$('#benchmark-summary').innerHTML='<p class="small-empty">No benchmark record is available.</p>';return;}const gateway=benchmark.model_gateway||benchmark.gateway||{},attempts=array(gateway.attempts),checks=array(benchmark.checks);$('#benchmark-summary').innerHTML=`<div class="requirement-top"><strong>${esc(benchmark.model||gateway.route?.label||'Recorded benchmark')}</strong>${badge(benchmark.status||'not recorded')}</div><p class="field-note">${esc(benchmark.scope||'Software and model checks are separate from experimentally validated chemical performance.')}</p><div class="benchmark-metrics">${roundMetric(gateway.attempted_calls??attempts.length,'recorded model attempts')}${roundMetric(checks.length,'benchmark checks')}${roundMetric(gateway.paid_api_cost_usd==null?'Not metered':'$'+fmt(gateway.paid_api_cost_usd,5),'paid API cost')}</div>${benchmark.error?`<p class="notice error">${esc(benchmark.error)}</p>`:''}${benchmark.scientific_reasoning_status?`<div class="notice ${/fail|reject/i.test(benchmark.scientific_reasoning_status)?'error':'info'}"><strong>Scientific reasoning: ${esc(human(benchmark.scientific_reasoning_status))}</strong><p>${esc(benchmark.scientific_review?.final_presentation_policy||'Scientific review is separate from structural contract checks. No experimental performance is established.')}</p><details><summary>Review findings</summary><ul>${array(benchmark.scientific_review?.findings).map(f=>`<li><strong>${esc(f.role||f.id||'Review')}:</strong> ${esc(f.finding||text(f))} ${esc(f.correction||'')}</li>`).join('')}</ul></details></div>`:''}${attempts.map(a=>`<div class="audit-row"><div><strong>${esc(a.role||a.id)}</strong><p>${esc(a.error||a.id||'')}</p></div>${badge(a.status||'not recorded')}</div>`).join('')}${checks.map(check=>`<div class="audit-row"><div><strong>${esc(check.name||check.id||check.case||'Check')}</strong><p>${esc(prose(check.description||check.result||check.notes,''))}</p></div>${badge(check.status||('passed'in check?(check.passed?'passed':'failed'):'recorded'))}</div>`).join('')}<details style="margin-top:20px"><summary class="muted">Exact benchmark, costs and attempt record</summary>${jsonBlock(benchmark)}</details>`;}
$('#refresh-benchmark').addEventListener('click',loadBenchmark);
async function start(){try{state.bootstrap=await api('/api/bootstrap');fillCampaignSelect();fillModels();renderBenchmark();const requestedCampaign=new URLSearchParams(location.search).get('campaign');const id=requestedCampaign&&campaignItems(state.bootstrap.campaigns).some(c=>c.id===requestedCampaign)?requestedCampaign:state.bootstrap.default_campaign_id||campaignItems(state.bootstrap.campaigns)[0]?.id;if(id)await loadCampaign(id);else{$('#campaign-name').textContent='Create your first study';$('#generate-button').disabled=true;}$('#connection-status').textContent='Local workspace connected';const initial=location.hash.slice(1);if(initial&&$('#'+initial+'-view'))view(initial);}catch(e){message('#global-error','Workspace could not load: '+e.message);$('#connection-status').textContent='Connection unavailable';$('#generate-button').disabled=true;}}
start();
